(()=>{
 let customers=[],loaded=false;
 const rows=document.querySelector('#customerRows'),search=document.querySelector('#customerSearch'),total=document.querySelector('#customerTotal');
 const modal=document.createElement('dialog');modal.className='modal order-modal';modal.id='customerDetailModal';modal.innerHTML='<div class="modal-inner"><div class="modal-head"><h2 id="customerDetailTitle">Detail pelanggan</h2><button class="close" type="button" aria-label="Tutup">×</button></div><div class="order-detail" id="customerDetailContent"></div></div>';document.body.append(modal);
 const content=modal.querySelector('#customerDetailContent');modal.querySelector('.close').addEventListener('click',()=>modal.close());modal.addEventListener('click',event=>{if(event.target===modal)modal.close()});
 const formatDate=value=>value?new Date(String(value).endsWith('Z')?value:`${value}Z`).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}):'—';
 function render(){const query=search.value.trim().toLowerCase(),filtered=customers.filter(item=>[item.name,item.email,item.phone].some(value=>String(value||'').toLowerCase().includes(query)));if(total)total.textContent=`${customers.length} pelanggan`;rows.innerHTML=filtered.length?filtered.map(item=>`<tr><td><strong>${escapeHtml(item.name)}</strong><br><small>${escapeHtml(item.email)}</small></td><td>${escapeHtml(item.phone||'—')}</td><td>${formatDate(item.createdAt)}</td><td>${item.orderCount}</td><td><strong>${rupiah(item.totalSpent)}</strong></td><td><button class="icon-btn customer-detail" data-id="${item.id}">Detail</button></td></tr>`).join(''):`<tr><td colspan="6" class="empty">${customers.length?'Pelanggan tidak ditemukan.':'Belum ada pelanggan terdaftar.'}</td></tr>`;rows.querySelectorAll('.customer-detail').forEach(button=>button.addEventListener('click',()=>openCustomer(Number(button.dataset.id))))}
 async function load(){if(loaded)return;rows.innerHTML='<tr><td colspan="6" class="empty">Memuat pelanggan…</td></tr>';try{const data=await api('/api/customers');customers=data.customers||[];loaded=true;render()}catch(error){rows.innerHTML=`<tr><td colspan="6" class="empty">${escapeHtml(error.message)}</td></tr>`}}
 async function openCustomer(id){const summary=customers.find(item=>item.id===id);document.querySelector('#customerDetailTitle').textContent=summary?.name||'Detail pelanggan';content.innerHTML='<div class="empty">Memuat detail pelanggan…</div>';modal.showModal();try{const data=await api(`/api/customers/${id}`),customer=data.customer,addresses=data.addresses||[],orders=data.orders||[];content.innerHTML=`<div class="order-summary-grid"><div class="order-box"><small>Kontak pelanggan</small><strong>${escapeHtml(customer.name)}</strong><div>${escapeHtml(customer.email)}</div><div>${escapeHtml(customer.phone||'Nomor telepon belum tersedia')}</div></div><div class="order-box"><small>Aktivitas akun</small><strong>Bergabung ${formatDate(customer.createdAt)}</strong><div>Login terakhir: ${formatDate(customer.lastLoginAt)}</div></div></div><div><strong>Alamat tersimpan</strong><div class="order-lines">${addresses.length?addresses.map(item=>`<div class="order-line"><span><strong>${escapeHtml(item.label)}</strong><small>${escapeHtml(item.address)}</small><small>${escapeHtml(item.city)} · ${escapeHtml(item.postalCode)}</small></span></div>`).join(''):'<div class="empty">Belum ada alamat tersimpan.</div>'}</div></div><div><strong>Riwayat pesanan</strong><div class="order-lines">${orders.length?orders.map(order=>`<div class="order-line"><span><strong>#${escapeHtml(order.id)}</strong><small>${formatDate(order.createdAt)} · ${escapeHtml(statusLabel[order.status]||order.status)} · ${escapeHtml(fulfillmentLabel[order.fulfillmentStatus]||'Menunggu')}</small></span><span style="text-align:right"><strong>${rupiah(order.total)}</strong><small><button class="link-btn customer-order" data-id="${escapeHtml(order.id)}">Buka pesanan</button></small></span></div>`).join(''):'<div class="empty">Belum ada pesanan.</div>'}</div></div>`;content.querySelectorAll('.customer-order').forEach(button=>button.addEventListener('click',()=>{modal.close();document.querySelector('.menu button[data-view="orders"]').click();openOrder(button.dataset.id)}))}catch(error){content.innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`}}
 search.addEventListener('input',render);document.querySelector('.menu button[data-view="customers"]').addEventListener('click',load);
})();
